package com.yeyamo_mobile.api.booking_service.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.data.domain.*;import com.yeyamo_mobile.api.booking_service.application.BookingDtos.BookingView;import com.yeyamo_mobile.api.booking_service.application.port.BookingOutboxPort;import com.yeyamo_mobile.api.booking_service.domain.*;import com.yeyamo_mobile.api.booking_service.infrastructure.persistence.*;
class AdminBookingServiceTest{BookingRepository bookings=mock(BookingRepository.class);BookingHistoryRepository history=mock(BookingHistoryRepository.class);BookingApplicationService commands=mock(BookingApplicationService.class);BookingOutboxPort outbox=mock(BookingOutboxPort.class);AdminBookingService service=new AdminBookingService(bookings,history,commands,outbox);
 @Test void listUsesDatabasePaginationAndFilters(){when(bookings.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class))).thenReturn(Page.empty());var result=service.list("ref",BookingStatus.CONFIRMED,"u","p",null,null,PaymentStatus.AUTHORIZED,null,null,null,null,PageRequest.of(0,20));assertTrue(result.isEmpty());verify(bookings).findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class));}
 @Test void unsupportedPlaceFilterReturnsEmptyWithoutInventingData(){assertTrue(service.list(null,null,null,null,"place",null,null,null,null,null,null,PageRequest.of(0,20)).isEmpty());verifyNoInteractions(bookings);}
 @Test void adminCancelDelegatesToLockedCommandAndAudits(){UUID id=UUID.randomUUID();BookingView view=mock(BookingView.class);when(commands.cancel("admin",id,"fraud","key","corr",true)).thenReturn(view);assertSame(view,service.cancel("admin",id,"fraud","key","corr"));verify(outbox).append(eq("booking.events"),eq("BOOKING_ADMIN_CANCELLED"),eq(id.toString()),eq("corr"),anyMap());}
 @Test void adminCompleteDelegatesTransitionAndAudits(){UUID id=UUID.randomUUID();BookingView view=mock(BookingView.class);when(commands.complete("admin",id,"key","corr",true)).thenReturn(view);assertSame(view,service.complete("admin",id,"key","corr"));verify(outbox).append(eq("booking.events"),eq("BOOKING_ADMIN_COMPLETED"),eq(id.toString()),eq("corr"),anyMap());}}
